import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { resolveTarget, stateFile } from "../lib/paths.js";
import { which } from "../lib/env.js";
import { logger } from "../lib/logger.js";
import { decideChannels, type Channels } from "../lib/ui.js";
import { writeState, type InstallState } from "../lib/version.js";
import { installChannels } from "../lib/plugins/index.js";

export interface InstallOptions {
  target?: string;
  yes?: boolean;
  with?: string;
  without?: string;
  all?: boolean;
  dryRun?: boolean;
}

interface EnvironmentProbe {
  node: boolean;
  npm: boolean;
  codegraph: boolean;
  entire: boolean;
}

function probeEnvironment(): EnvironmentProbe {
  return {
    node: which("node") !== null,
    npm: which("npm") !== null,
    codegraph: which("codegraph") !== null,
    entire: which("entire") !== null,
  };
}

function paintInstalled(channel: string): string {
  return `\u2713 ${channel}`;
}

function printChannelSummary(channels: Channels): void {
  logger.info("Channels installed:");
  logger.info(`  ${paintInstalled("core")} (always)`);
  logger.info(`  ${channels.codegraph ? paintInstalled("codegraph") : "  codegraph"}`);
  logger.info(`  ${channels.entire ? paintInstalled("entire") : "  entire"}`);
}

function readExistingState(target: string): InstallState | undefined {
  const file = stateFile(target);
  if (!existsSync(file)) return undefined;
  try {
    const raw = readFileSync(file, "utf8");
    return JSON.parse(raw) as InstallState;
  } catch {
    return undefined;
  }
}

function appendGitignoreRule(target: string): void {
  const gitignore = join(target, ".gitignore");
  if (!existsSync(gitignore)) return;
  const existing = readFileSync(gitignore, "utf8");
  if (existing.includes(".pi/.pisquad/")) return;
  const sep = existing.endsWith("\n") ? "" : "\n";
  writeFileSync(gitignore, `${existing}${sep}.pi/.pisquad/\n`, "utf8");
  logger.info("appended .pi/.pisquad/ to .gitignore");
}

/**
 * Full install pipeline. The Commander layer (main.ts) routes here.
 *
 * Behavioural contract:
 * - Refuses to run when <target>/.pi/.pisquad/state.json already exists; the
 *   user must use `pisquad upgrade` instead.
 * - Refuses when node or npm are missing (hard requirement for core).
 * - Refuses only when an optional channel is requested AND its host CLI is
 *   missing.
 * - Honors the non-interactive contract: no tty + no flags → core only, exit 0.
 * - Honors --dry-run end-to-end (no writes, including state.json).
 */
export async function installCommand(options: InstallOptions): Promise<void> {
  const target = resolveTarget(options.target);
  const env = probeEnvironment();
  const dryRun = options.dryRun === true;

  logger.info(`pisquad install → ${target}${dryRun ? " (dry-run)" : ""}`);

  if (!env.node || !env.npm) {
    logger.error("node and npm are required to install pi-squad");
    logger.error("install Node.js 18+ from https://nodejs.org/ (which includes npm) and try again");
    process.exitCode = 1;
    return;
  }

  const existing = readExistingState(target);
  if (existing) {
    logger.error("pi-squad is already installed in this directory");
    logger.error(`state file: ${stateFile(target)}`);
    logger.error("re-run with \`pisquad upgrade\` to update an existing installation");
    logger.error("(upgrade lands in stage 2; for now, remove the state file or pick another target)");
    process.exitCode = 1;
    return;
  }

  const channels = await decideChannels({
    all: options.all,
    with: options.with,
    without: options.without,
    yes: options.yes,
    target,
  });

  // Gate optional channels on their host CLI availability.
  if (channels.codegraph && !env.codegraph) {
    logger.error("channel 'codegraph' was requested but the codegraph CLI is not on PATH");
    logger.error("install it from https://github.com/... (or omit 'codegraph' from --with / --all)");
    process.exitCode = 1;
    return;
  }
  if (channels.entire && !env.entire) {
    logger.error("channel 'entire' was requested but the entire CLI is not on PATH");
    logger.error("install it from https://entire.io (or omit 'entire' from --with / --all)");
    process.exitCode = 1;
    return;
  }

  try {
    await installChannels(target, channels, { dryRun });
  } catch (error) {
    logger.error(`install failed: ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
    return;
  }

  if (dryRun) {
    logger.info("DRY RUN — no changes made");
    return;
  }

  writeState(target, { channels });
  appendGitignoreRule(target);

  printChannelSummary(channels);
  logger.success("install complete");
  logger.info(`state file: ${stateFile(target)}`);
}

import { copyDir } from "../copy.js";
import { resolveAsset } from "../paths.js";
import { execFile } from "node:child_process";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { promisify } from "node:util";
import type { PluginOptions } from "./types.js";

const execFileAsync = promisify(execFile);

const ENABLE_TIMEOUT_MS = 30 * 1000; // 30s — entire enable should be fast

/**
 * Install the entire extension into the target.
 *
 * This plugin fixes the long-standing bash installer bug where selecting the
 * "entire" channel only ran `entire enable --agent pi` without first copying
 * the extension source directory, leaving consumers with a half-installed
 * extension. Both steps now happen here, in this order:
 *
 *   1. Copy assets/.pi/extensions/entire → <target>/.pi/extensions/entire
 *   2. Run `entire enable --agent pi` (idempotent, best-effort)
 */
export async function installEntire(target: string, opts: PluginOptions): Promise<void> {
  const logger = opts.logger;
  const source = resolveAsset(".pi/extensions/entire");
  const destination = join(target, ".pi", "extensions", "entire");

  if (!existsSync(source)) {
    logger.warn(`Missing entire asset directory: ${source}`);
    return;
  }

  if (opts.dryRun) {
    copyDir(source, destination, { dryRun: true });
    logger.info(`[dry-run] entire enable --agent pi (skipped)`);
    return;
  }

  // Step 1: copy the extension directory (the bug fix).
  copyDir(source, destination);
  logger.info(`copied extensions/entire → ${destination}`);

  // Step 2: register with entire (best-effort — entire may not be installed yet).
  try {
    logger.info(`running entire enable --agent pi`);
    await execFileAsync("entire", ["enable", "--agent", "pi"], {
      cwd: target,
      timeout: ENABLE_TIMEOUT_MS,
      maxBuffer: 4 * 1024 * 1024,
    });
  } catch (error) {
    logger.warn(`entire enable --agent pi failed (non-fatal): ${error instanceof Error ? error.message : String(error)}`);
    logger.warn(`re-run \`entire enable --agent pi\` inside ${target} once Entire CLI is installed`);
  }
}

import { copyDir } from "../copy.js";
import { resolveAsset } from "../paths.js";
import { atomicWriteFile } from "../fs-safe.js";
import { join } from "node:path";
import { existsSync } from "node:fs";
import type { PluginOptions } from "./types.js";

const EXTENSION_DIRS = new Set([
  "extensions/subagent",
  "extensions/wikilink-lint",
  "extensions/codegraph",
  "extensions/entire",
]);

/**
 * Copy the "core" payload (agents, skills, every extension's source tree).
 *
 * node_modules and package-lock.json are stripped from extension directories
 * during the core copy — `installCodegraph` materialises them via `npm install`
 * when the channel is enabled, and the entire/subagent/wikilink-lint extensions
 * have no runtime dependencies of their own.
 */
export async function installCore(target: string, opts: PluginOptions): Promise<void> {
  const logger = opts.logger;
  const baseAsset = resolveAsset(".pi");

  const simpleDirs = ["agents", "skills"];
  for (const sub of simpleDirs) {
    const source = join(baseAsset, sub);
    const destination = join(target, ".pi", sub);
    if (!existsSync(source)) {
      logger.warn(`Skipping missing asset directory: ${source}`);
      continue;
    }
    if (opts.dryRun) {
      copyDir(source, destination, { dryRun: true });
    } else {
      copyDir(source, destination);
    }
    logger.info(`copied ${sub} → .pi/${sub}`);
  }

  for (const sub of EXTENSION_DIRS) {
    const source = join(baseAsset, sub);
    const destination = join(target, ".pi", sub);
    if (!existsSync(source)) {
      if (opts.dryRun) {
        logger.info(`[dry-run] skip missing: assets/.pi/${sub}`);
      } else {
        logger.warn(`Skipping missing asset directory: ${source}`);
      }
      continue;
    }
    const options = {
      filter: (_abs: string, rel: string) => rel !== "node_modules" && rel !== "package-lock.json",
      ...(opts.dryRun ? { dryRun: true } : {}),
    };
    copyDir(source, destination, options);
    logger.info(`copied ${sub} → .pi/${sub}`);
  }

  // Pin the .pi/.gitignore so users do not accidentally check node_modules in.
  const gitignorePath = join(target, ".pi", ".gitignore");
  if (opts.dryRun) {
    logger.info(`[dry-run] write ${gitignorePath}`);
  } else if (!existsSync(gitignorePath)) {
    atomicWriteFile(gitignorePath, "node_modules\n");
  }
}

import { readFileSync } from "node:fs";
import { resolvePackageRoot, resolveAsset, stateFile } from "./paths.js";
import { atomicWriteFile, ensureDir, pathExists } from "./fs-safe.js";
import { readAssetsVersion } from "./assets.js";

/**
 * Install state recorded in <target>/.pi/.pisquad/state.json.
 * Mirrors docs/conventions/install-state.md.
 */
export interface InstallState {
  version: string;
  cliVersion: string;
  channels: {
    core: true;
    codegraph: boolean;
    entire: boolean;
  };
  installedAt: string;
  lastUpgradedAt?: string;
}

export interface WriteStateInput {
  version?: string;
  cliVersion?: string;
  channels: InstallState["channels"];
  installedAt?: string;
  lastUpgradedAt?: string;
}

/** Read the CLI version embedded in package.json. */
export function readCliVersion(): string {
  const pkgPath = `${resolvePackageRoot()}/package.json`;
  try {
    const raw = readFileSync(pkgPath, "utf8");
    const parsed = JSON.parse(raw) as { version?: unknown };
    if (typeof parsed.version === "string" && parsed.version.length > 0) {
      return parsed.version;
    }
  } catch (error) {
    throw new Error(`Unable to read CLI version from ${pkgPath}`, { cause: error });
  }
  throw new Error(`CLI version missing in ${pkgPath}`);
}

/**
 * Resolve the assets content version. Falls back to the CLI version when the
 * assets-version.txt file is not shipped yet (early bootstrap / missing file).
 *
 * Use for display / UX paths only. For state writes, prefer `readAssetsVersion`
 * directly so a missing or unreadable assets-version.txt surfaces as an error
 * rather than being silently papered over.
 */
export function resolveAssetsVersion(fallback: string = readCliVersion()): string {
  try {
    return readAssetsVersion();
  } catch {
    return fallback;
  }
}

/**
 * Strict reader for <target>/.pi/.pisquad/state.json.
 *
 * Returns the parsed state only when every required field has the expected
 * shape (version, cliVersion, installedAt, channels). When the file is
 * missing, unparseable, or structurally invalid, returns undefined so the
 * caller can decide whether to treat the target as not-yet-installed.
 *
 * Note: this function never throws — validation failures map to `undefined`.
 */
export function readState(target: string): InstallState | undefined {
  const file = stateFile(target);
  if (!pathExists(file)) return undefined;
  try {
    const raw = readFileSync(file, "utf8");
    const parsed = JSON.parse(raw) as Partial<InstallState> | null;
    if (!parsed || typeof parsed !== "object") return undefined;
    if (
      typeof parsed.version !== "string" ||
      typeof parsed.cliVersion !== "string" ||
      typeof parsed.installedAt !== "string" ||
      !parsed.channels ||
      typeof parsed.channels !== "object"
    ) {
      return undefined;
    }
    const channels = parsed.channels as Partial<InstallState["channels"]>;
    if (
      channels.core !== true ||
      typeof channels.codegraph !== "boolean" ||
      typeof channels.entire !== "boolean"
    ) {
      return undefined;
    }
    if (parsed.lastUpgradedAt !== undefined && typeof parsed.lastUpgradedAt !== "string") {
      return undefined;
    }
    return parsed as InstallState;
  } catch {
    return undefined;
  }
}

/**
 * Persist the install state at <target>/.pi/.pisquad/state.json.
 *
 * Rules (see docs/conventions/install-state.md):
 * - `installedAt` is preserved across rewrites once set; first write sets it to now()
 * - `lastUpgradedAt` is preserved when the caller does not provide a new value
 * - `channels.core` is forced to true regardless of caller input
 * - Missing `version` / `cliVersion` are filled from assets + package metadata
 * - Writes are atomic (fs-safe.atomicWriteFile)
 */
export function writeState(target: string, partial: WriteStateInput): InstallState {
  const existing = readState(target);
  const now = new Date().toISOString();
  const cliVersion = partial.cliVersion ?? existing?.cliVersion ?? readCliVersion();
  const version = partial.version ?? existing?.version ?? readAssetsVersion();

  const next: InstallState = {
    version,
    cliVersion,
    channels: {
      core: true,
      codegraph: partial.channels?.codegraph ?? existing?.channels.codegraph ?? false,
      entire: partial.channels?.entire ?? existing?.channels.entire ?? false,
    },
    installedAt: partial.installedAt ?? existing?.installedAt ?? now,
  };

  if (partial.lastUpgradedAt !== undefined) {
    next.lastUpgradedAt = partial.lastUpgradedAt;
  } else if (existing?.lastUpgradedAt !== undefined) {
    next.lastUpgradedAt = existing.lastUpgradedAt;
  }

  const file = stateFile(target);
  ensureDir(`${target}/.pi/.pisquad`);
  atomicWriteFile(file, JSON.stringify(next, null, 2) + "\n");
  return next;
}

// Re-export paths helpers used in conjunction with state files.
export { resolveAsset, stateFile };

import { createHash } from "node:crypto";
import { createReadStream, lstatSync, readdirSync } from "node:fs";
import { join, relative, sep } from "node:path";
import { resolveAsset } from "./paths.js";

/** Map of relative path (POSIX-style, forward slashes) → lowercase hex sha256. */
export interface FileHashMap {
  [relPath: string]: string;
}

export interface Sha256DirOptions {
  /** Return true to skip a relative path. Applied recursively inside the tree. */
  ignore?: (relPath: string) => boolean;
}

/**
 * Pair one subtree inside the pisquad package with the matching subtree inside
 * the install target. The two subtrees are walked independently and their
 * relative paths are merged into one logical tree for diffing.
 *
 * IMPORTANT: the caller MUST include the `docs` subtree
 * (`{ pkgSubPath: "docs", targetSubPath: "docs" }`) — see PRD §6 "upgrade 安
 * 全机制": docs is the most frequently consumer-edited area and must be
 * diffed alongside `.pi` so the upgrader can detect user modifications and
 * back them up.
 */
export interface PkgInclude {
  /** Subtree under the package's `assets/` directory, e.g. ".pi" or "docs". */
  pkgSubPath: string;
  /** Matching subtree inside the install target, e.g. ".pi" or "docs". */
  targetSubPath: string;
}

export interface DiffTreeOptions {
  /** Skip a relative path on BOTH sides. Defaults to `defaultIgnore`. */
  ignore?: (relPath: string) => boolean;
  /**
   * Override the directory pkg subpaths are resolved against. Defaults to
   * `resolveAsset` (i.e. `<package root>/assets`). Tests use this to point at
   * a synthetic assets tree without mutating the shipped assets.
   */
  assetsRoot?: string;
}

export interface DiffPlan {
  /** Present in both, hash differs — back up then overwrite. */
  modified: Array<{ relPath: string; fromHash: string; toHash: string }>;
  /** Only in pkg — copy into target (no backup needed). */
  added: Array<{ relPath: string; toHash: string }>;
  /** Only in target — kept by default; only deleted when `--prune` is passed. */
  removed: Array<{ relPath: string; fromHash: string }>;
  /** Present in both, same hash — informational. */
  unchanged: Array<{ relPath: string }>;
}

/**
 * Runtime / tool-generated entries that do not count as "user modifications"
 * and are therefore excluded from the diff on both sides:
 *
 * - `node_modules/` — restored by `npm install` after every channel copy
 * - `.pisquad/` — pisquad's own state.json + backups
 * - `.codegraph/` — codegraph CLI's tool-generated cache
 * - `.entire/` — entire CLI's tool-generated metadata
 * - `.DS_Store` — macOS Finder debris
 */
export const DEFAULT_IGNORE_NAMES = new Set([
  "node_modules",
  ".pisquad",
  ".codegraph",
  ".entire",
  ".DS_Store",
]);

/** Default ignore predicate: true for any path whose any segment is in DEFAULT_IGNORE_NAMES. */
export function defaultIgnore(relPath: string): boolean {
  return relPath.split("/").some((segment) => DEFAULT_IGNORE_NAMES.has(segment));
}

/** Compute the sha256 of a single file as lowercase hex. */
export function sha256File(path: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const hash = createHash("sha256");
    const stream = createReadStream(path);
    stream.on("error", reject);
    stream.on("data", (chunk: Buffer | string) => hash.update(chunk));
    stream.on("end", () => resolve(hash.digest("hex")));
  });
}

/**
 * Recursively hash every regular file under `root`. Returns a map keyed by
 * POSIX-style relative paths from `root`. Symlinks are skipped (not followed)
 * to match the conservative behaviour of `copy.ts`.
 */
export async function sha256Dir(root: string, opts: Sha256DirOptions = {}): Promise<FileHashMap> {
  const result: FileHashMap = {};

  const walk = async (dir: string): Promise<void> => {
    let entries;
    try {
      entries = readdirSync(dir, { withFileTypes: true });
    } catch {
      // Missing directory → empty contribution. Lets `diffTree` treat the
      // other side as the authoritative source of entries.
      return;
    }
    for (const entry of entries) {
      const full = join(dir, entry.name);
      const stat = lstatSync(full);
      // Symlinks are skipped for parity with copy.ts: following them could
      // escape the source tree or surface targets the caller never meant to
      // ship. The asset tree has no symlinks today, but upgrade diffs walk
      // user trees where symlinks are real.
      if (stat.isSymbolicLink()) continue;

      const rel = relative(root, full).split(sep).join("/");
      if (opts.ignore?.(rel)) continue;

      if (stat.isDirectory()) {
        await walk(full);
      } else if (stat.isFile()) {
        result[rel] = await sha256File(full);
      }
      // Other entry types (sockets, devices, fifos) are silently ignored — they
      // have no place in a sha256 diff.
    }
  };

  await walk(root);
  return result;
}

/**
 * Compare the package's payload subtrees against the matching subtrees in the
 * install target.
 *
 * The returned `modified` (and, if `--prune` is in play, `removed`) entries
 * use paths relative to the install target, so they can be passed straight
 * into `backup.createBackup` and `copy.copyDir` without re-mapping.
 */
export async function diffTree(
  target: string,
  pkgIncludes: PkgInclude[],
  opts: DiffTreeOptions = {},
): Promise<DiffPlan> {
  const ignore = opts.ignore ?? defaultIgnore;
  const assetsRoot = opts.assetsRoot;

  // Build fromHash (target, current install) and toHash (pkg, new version)
  // maps. Both are keyed by relPath from the matching subtree base, so as long
  // as pkgSubPath === targetSubPath the key spaces line up and the merge is
  // direct. pkgSubPath is resolved against the package's assets/ directory —
  // the same convention installCore uses (`resolveAsset`).
  const fromHash: FileHashMap = {};
  const toHash: FileHashMap = {};

  for (const inc of pkgIncludes) {
    const pkgAbs = assetsRoot ? join(assetsRoot, inc.pkgSubPath) : resolveAsset(inc.pkgSubPath);
    const targetAbs = join(target, inc.targetSubPath);
    const pkgMap = await sha256Dir(pkgAbs, { ignore });
    const targetMap = await sha256Dir(targetAbs, { ignore });
    // Re-key both maps with the targetSubPath prefix so the merged maps are
    // keyed by relPath-from-target (e.g. `docs/README.md`, `.pi/agents/a.md`).
    // That makes the plan entries directly usable by backup.createBackup and
    // copy.copyDir, which join them onto `target`.
    const prefix = inc.targetSubPath;
    for (const [rel, hash] of Object.entries(pkgMap)) {
      const key = prefix ? `${prefix}/${rel}` : rel;
      toHash[key] = hash;
    }
    for (const [rel, hash] of Object.entries(targetMap)) {
      const key = prefix ? `${prefix}/${rel}` : rel;
      fromHash[key] = hash;
    }
  }

  const plan: DiffPlan = { modified: [], added: [], removed: [], unchanged: [] };
  const seen = new Set<string>();
  for (const [rel, toHashValue] of Object.entries(toHash)) {
    seen.add(rel);
    if (!(rel in fromHash)) {
      plan.added.push({ relPath: rel, toHash: toHashValue });
    } else if (fromHash[rel] !== toHashValue) {
      plan.modified.push({ relPath: rel, fromHash: fromHash[rel], toHash: toHashValue });
    } else {
      plan.unchanged.push({ relPath: rel });
    }
  }
  for (const rel of Object.keys(fromHash)) {
    if (seen.has(rel)) continue;
    plan.removed.push({ relPath: rel, fromHash: fromHash[rel] });
  }

  // Deterministic output for tests + predictable upgrade logs.
  const byRel = (a: { relPath: string }, b: { relPath: string }): number =>
    a.relPath.localeCompare(b.relPath);
  plan.modified.sort(byRel);
  plan.added.sort(byRel);
  plan.removed.sort(byRel);
  plan.unchanged.sort(byRel);

  return plan;
}

